/**  Change nothing; list what would change. */
"check" | 
/**  Make the changes. */
"apply";

/**  Which screen the webview shows for a session window. */
export type Screen = 
/**  No session: the connect / profiles form. */
"profiles" | 
/**  Connecting progress. */
"connecting" | 
/**  An unknown certificate needs a decision. */
"certificate" | 
/**  Remote Login greeter is live: a non-modal hint banner over the picture. */
"greeter-hint" | 
/**  Backoff overlay over the dimmed last frame: "Reconnecting in N s… [Now] [Cancel]". */
"reconnecting" | 
/**  Ended with an explanation and next steps. */
"error" | 
/**  Live desktop: the webview is hidden, unless the statistics HUD is switched on. */
"live";

/**  Password changes submitted with a profile. Empty strings mean "unchanged". */
export type SecretsUpdate = {
	/**  New RDP password for the profile's mode (`None` = keep the stored one). */
	rdp_password: string | null,
	/**  Linux password opt-in (Remote Login only; ignored and forgotten for other modes). */
	linux_password: LinuxPasswordUpdate,
};

/**  Lifecycle of one session (window), plan §3. */
export type SessionState = SessionState_Serialize | SessionState_Deserialize;

/**  Lifecycle of one session (window), plan §3. */
export type SessionState_Deserialize = 
/**  Not started. */
({ state: "idle" }) & { attempt?: never; desktop?: never; leg?: never; next_in?: never; reason?: never; scale?: never; stage?: never } | 
/**  Establishing connection leg `leg` (1-based, `1..=MAX_LEG`). */
({ state: "connecting"; 
/**  Connection leg (1 = initial, ≥ 2 = after a Server Redirection). */
leg: number; 
/**  Progress within the leg. */
stage: ConnectStage }) & { attempt?: never; desktop?: never; next_in?: never; reason?: never; scale?: never } | 
/**  Remote Login: the GDM greeter is visible and the user must log in. */
({ state: "awaiting-greeter-login" }) & { attempt?: never; desktop?: never; leg?: never; next_in?: never; reason?: never; scale?: never; stage?: never } | 
/**  A live desktop is displayed. */
({ state: "connected"; 
/**  Remote desktop size in pixels. */
desktop: Size<number>; 
/**  `DesktopScaleFactor` in percent (100 or 200). */
scale: number }) & { attempt?: never; leg?: never; next_in?: never; reason?: never; stage?: never } | 
/**  Waiting to retry after a retryable disconnect. */
({ state: "reconnecting"; 
/**  1-based attempt number. */
attempt: number; 
/**  Delay until the next attempt (serialized as integer milliseconds). */
next_in: number; 
/**  The retryable reason that triggered reconnection. */
reason: DisconnectReason }) & { desktop?: never; leg?: never; scale?: never; stage?: never } | 
/**  Stopped; the user may reconnect manually. */
({ state: "disconnected"; 
/**  Why. */
reason: DisconnectReason }) & { attempt?: never; desktop?: never; leg?: never; next_in?: never; scale?: never; stage?: never } | 
/**  Stopped with an error that needs user action. */
({ state: "failed"; 
/**  Why. */
reason: DisconnectReason }) & { attempt?: never; desktop?: never; leg?: never; next_in?: never; scale?: never; stage?: never };

