/**  Why a run did not start or did not finish. */
export type SetupError = 
/**  Sign in first. */
{ kind: "not-signed-in" } | 
/**  The options need fixing. */
{ kind: "invalid"; 
/**  The fields to fix. */
issues: SetupIssue[] } | 
/**  The account needs its password for sudo. */
{ kind: "sudo-password-needed" } | 
/**  sudo did not accept the password. */
{ kind: "sudo-password-rejected" } | 
/**  The connection failed. */
{ kind: "ssh"; 
/**  What went wrong. */
diagnosis: Diagnosis };

/**  A setup option the wizard must ask about again. */
export type SetupIssue = 
/**  The connection needs a name. */
"name" | 
/**  Not a Linux account name. */
"account" | 
/**  Not a TCP port. */
"port" | 
/**  The headless port is Remote Login's. */
"port-taken-by-remote-login" | 
/**  The RDP user name is empty or has control characters. */
"rdp-username" | 
/**  The RDP password is shorter than 8 characters or has control characters. */
"rdp-password" | 
/**  Not a network address with an optional prefix length. */
"allow-from";

/**  One line of `drift-host-setup.sh` output. */
export type SetupLine = 
/**  `drift-host-setup: mode=…`. */
{ kind: "mode"; 
/**  The run's mode. */
mode: RunMode } | 
/**  `ok:` — already as wanted. */
{ kind: "ok"; 
/**  What is fine. */
text: string } | 
/**  `would:` — `--check` would change this. */
{ kind: "would"; 
/**  What would change. */
text: string } | 
/**  The `$ command` line under a `would:`. */
{ kind: "command"; 
/**  The command. */
text: string } | 
/**  `change:` — `--apply` is changing this. */
{ kind: "change"; 
/**  What changes. */
text: string } | 
/**  `skip:` — not checked yet. */
{ kind: "skip"; 
/**  What was skipped. */
text: string } | 
/**  `wait:` — waiting for something to start. */
{ kind: "wait"; 
/**  What it waits for. */
text: string } | 
/**  `error:`. */
{ kind: "error"; 
/**  The error. */
text: string } | 
/**  `fingerprint: OWNER aa:bb:…` — a daemon's certificate. */
{ kind: "fingerprint"; 
/**  `system` or the headless account. */
owner: string; 
/**  The certificate's SHA-256. */
fingerprint: CertFingerprint } | 
/**  `drift-host-setup: N change(s) …, M error(s)`. */
{ kind: "summary"; 
/**  Changes pending or applied. */
changes: number; 
/**  Errors. */
errors: number } | 
/**  Anything else (package manager output). */
{ kind: "output"; 
/**  The line. */
text: string };

/**  One line of the running setup's output, sent to the window that started it. */
export type SetupLineEmitted = {
	/**  The parsed line. */
	line: SetupLine,
};

/**  What the wizard sets up on one machine. */
export type SetupOptions = {
	/**  The connection's name in Drift. */
	name: string,
	/**  The Linux account that gets the persistent headless session. */
	account: string,
	/**  The headless session's RDP port. */
	port: number,
	/**  The RDP user name. */
	rdp_username: string,
	/**  The RDP password to set; `None` keeps the credentials already on the machine. */
	rdp_password: string | null,
	/**  Also set up Remote Login (GNOME's login screen on port 3389). */
	remote_login: boolean,
	/**  Install a minimal GNOME when GNOME Shell or GDM is missing. */
	install_desktop: boolean,
	/**  Open the ports in ufw or firewalld. */
	open_firewall: boolean,
	/**  Open them only to this network (`10.0.0.0/21`, `fd00::/64`). */
	allow_from: string | null,
};

/**  What a finished run reported. */
export type SetupResult = SetupResult_Serialize | SetupResult_Deserialize;

/**  What a finished run reported. */
export type SetupResult_Deserialize = {
	/**  How it ended. */
	outcome: Outcome,
	/**  The script's `error:` lines. */
	errors: string[],
	/**  Changes pending (check) or applied (apply), from the summary line. */
	changes: number | null,
	/**  After a successful apply: the unsaved connections, certificates pinned. */
	profiles: ConnectionProfile_Deserialize[],
};

/**  What a finished run reported. */
export type SetupResult_Serialize = {
	/**  How it ended. */
	outcome: Outcome,
	/**  The script's `error:` lines. */
	errors: string[],
	/**  Changes pending (check) or applied (apply), from the summary line. */
	changes: number | null,
	/**  After a successful apply: the unsaved connections, certificates pinned. */
	profiles: ConnectionProfile_Serialize[],
};

/**  Where signing in got to. */
export type SignIn = 
/**  Signed in; `sudo` says whether the run needs the account's password. */
{ kind: "ready"; 
/**  How the run gets root. */
sudo: Sudo } | 
/**  Not signed in, and why (the wizard offers the fix). */
{ kind: "problem"; 
/**  What went wrong. */
diagnosis: Diagnosis };

/**  A 2-D size. `Size<u32>` is used for pixels, `Size<f64>` for AppKit points. */
export type Size<T> = {
	/**  Horizontal extent. */
	width: T,
	/**  Vertical extent. */
	height: T,
};

/**
 *  One statistics sample, quantised to what the HUD actually prints.
 * 
 *  [`drift_rdp::SessionStats`] is sampled about once per second; the numbers are rounded to one
 *  decimal here so that two samples that would draw the same line compare equal and the view is
 *  not re-emitted (plan M1 "Done (manual M1)", M9-1).
 */
export type StatsView = {
	/**  Presented frames per second, in tenths (`589` prints as `58.9 fps`). */
	fps_tenths: number,
	/**  Received payload bit rate, in tenths of a Mbit/s. */
	mbit_tenths: number,
	/**  Decode + present latency, 95th percentile, in tenths of a millisecond. */
	latency_p95_tenths_ms: number,
	/**  Frames awaiting acknowledgement. */
	unacked_frames: number,
};

/**  How the run gets root on the machine. */
export type Sudo = 
/**  The account has passwordless sudo (`sudo -n`). */
"passwordless" | 
/**  sudo reads the account's password from the first line of stdin (`sudo -S`). */
"password";

/**  The machine and account to sign in to. */
export type Target = {
	/**  Host name or address. */
	host: string,
	/**  SSH port. */
	port: number,
	/**  Account. */
	user: string,
};

/**
 *  A live session's preview for its gallery card, as a `data:image/png;base64,…` URL.
 *  `image: None` drops the preview (the session ended). Never logged, never written to disk.
 */
export type Thumbnail = {
	/**  The profile whose card shows it. */
	profile_id: string,
	/**  The PNG as a data URL, or `None`. */
	image: string | null,
};

/**  Emitted to the `connections` page only, while it is visible. */
export type ThumbnailUpdated = Thumbnail;

/**  How a finger on the picture drives the remote pointer on iPhone and iPad (IOS-7). */
export type TouchMode = 
/**  The device decides: trackpad on iPhone, direct on iPad. Default. */
"auto" | 
/**  The screen is a trackpad: relative pointer, taps click where the pointer is. */
"trackpad" | 
/**  Tap where you touch. */
"direct";

/**  What to do with a host key that is not recorded yet. */
export type Trust = 
/**  Stop and report it. */
"known-only" | 
/**  Record it (the wizard's "Trust and Connect"). */
"trust-new";

/**  A session window's title bar: the identity capsule and the buttons. */
export type WindowIdentity = {
	/**  The window's profile. */
	profile_id: string,
	/**  Display name. */
	name: string,
	/**  Host as saved in the profile. */
	host: string,
	/**  Connection mode (a GNOME computer's capsule names it). */
	mode: ConnectMode,
	/**  Dot or spinner. */
	status: ConnectionStatus,
	/**  Greeter hint (tooltip) while the GNOME login screen waits. */
	hint: string | null,
	/**  The statistics HUD is on (gauge pressed). */
	show_stats: boolean,
};

/**  Emitted to a session window's `<label>-titlebar` webview (identical pushes are skipped). */
export type WindowIdentityChanged = WindowIdentity;

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

